<template>
  <ion-page class="cms-page"><AppHeader variant="admin" title="Kelola Konten" />
    <ion-content :fullscreen="true"><main class="cms-shell">
      <header class="cms-intro"><p class="eyebrow">CMS PoliLand</p><h1>Kelola konten publik</h1><p>Perbarui informasi website tanpa menyentuh source code.</p></header>
      <nav class="tabs" aria-label="Modul konten"><button v-for="tab in tabs" :key="tab.key" :class="{ active: current === tab.key }" type="button" @click="current = tab.key">{{ tab.label }}</button></nav>
      <p v-if="notice" class="notice" :class="noticeType" role="status">{{ notice }}</p>
      <section v-if="loading" class="state">Memuat data konten…</section>
      <template v-else>
        <section v-if="current === 'home'" class="panel"><div class="panel-heading"><div><h2>Beranda</h2><p>Hero dan keunggulan yang tampil di halaman utama.</p></div><button class="primary" type="button" :disabled="saving" @click="saveHome">{{ saving ? 'Menyimpan…' : 'Simpan perubahan' }}</button></div>
          <div class="form-grid"><label>Judul utama<input v-model="hero.title" required></label><label>Subjudul<input v-model="hero.subtitle"></label><label class="wide">Deskripsi<textarea v-model="hero.description" rows="3"></textarea></label><label>Teks tombol<input v-model="hero.cta_text"></label><label>Tujuan tombol<input v-model="hero.cta_url" type="url"></label><label class="wide">Gambar utama<input type="file" accept="image/jpeg,image/png,image/webp" @change="selectHeroImage"><img v-if="heroPreview || hero.image_url" :src="heroPreview || hero.image_url || ''" alt="Pratinjau hero" class="hero-preview"></label></div>
          <div class="subheading"><h3>Keunggulan</h3><button class="secondary" type="button" @click="addFeature">Tambah keunggulan</button></div><div v-for="(feature, index) in features" :key="feature.id || index" class="feature-row"><input v-model="feature.icon" aria-label="Icon"><input v-model="feature.title" aria-label="Judul keunggulan" placeholder="Judul"><input v-model="feature.description" aria-label="Deskripsi keunggulan" placeholder="Deskripsi"><input v-model.number="feature.sort_order" aria-label="Urutan" type="number" min="0"><button class="danger" type="button" @click="removeFeature(feature, index)">Hapus</button></div>
        </section>
        <CmsCrudPanel v-else :type="current" @notify="showNotice" />
      </template>
    </main></ion-content><MobileTabBar variant="admin" />
  </ion-page>
</template>
<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'; import { IonContent, IonPage } from '@ionic/vue'; import AppHeader from '@/components/common/AppHeader.vue'; import MobileTabBar from '@/components/common/MobileTabBar.vue'; import CmsCrudPanel from '@/components/Admin/CmsCrudPanel.vue'; import { cmsService, type CmsFeature, type CmsHero } from '@/services/cmsService'
const tabs = [{ key: 'home', label: 'Beranda' }, { key: 'gallery', label: 'Gallery' }, { key: 'progress', label: 'Progress' }, { key: 'faq', label: 'FAQ' }, { key: 'contact', label: 'Kontak' }] as const; const current = ref<typeof tabs[number]['key']>('home'); const loading = ref(true); const saving = ref(false); const notice = ref(''); const noticeType = ref('success'); const hero = reactive<CmsHero>({ title: '', subtitle: '', description: '', cta_text: 'Hubungi Kami', cta_url: '/contact', is_active: true }); const features = ref<CmsFeature[]>([]); const heroPreview = ref(''); const selectedImage = ref<File | null>(null)
function showNotice(message: string, type = 'success') { notice.value = message; noticeType.value = type; window.setTimeout(() => notice.value = '', 3500) }
async function load() { try { const [savedHero, savedFeatures] = await Promise.all([cmsService.getHero(true), cmsService.getFeatures()]); if (savedHero) Object.assign(hero, savedHero); features.value = savedFeatures } catch (e) { showNotice(e instanceof Error ? e.message : 'Gagal memuat konten.', 'error') } finally { loading.value = false } }
function addFeature() { features.value.push({ icon: 'leaf', title: '', description: '', sort_order: features.value.length, is_active: true }) }
async function removeFeature(feature: CmsFeature, index: number) { if (!confirm('Hapus keunggulan ini?')) return; try { if (feature.id) await cmsService.deleteFeature(feature.id); features.value.splice(index, 1); showNotice('Keunggulan dihapus.') } catch (e) { showNotice(e instanceof Error ? e.message : 'Gagal menghapus.', 'error') } }
function selectHeroImage(event: Event) { const file = (event.target as HTMLInputElement).files?.[0]; if (!file) return; selectedImage.value = file; heroPreview.value = URL.createObjectURL(file) }
async function saveHome() { if (!hero.title.trim()) return showNotice('Judul utama wajib diisi.', 'error'); saving.value = true; try { if (selectedImage.value) hero.image_url = await cmsService.uploadImage(selectedImage.value); await cmsService.saveHero(hero); await Promise.all(features.value.map((feature) => cmsService.saveFeature(feature))); showNotice('Konten beranda berhasil disimpan.') } catch (e) { showNotice(e instanceof Error ? e.message : 'Gagal menyimpan konten.', 'error') } finally { saving.value = false } }
onMounted(load)
</script>
<style scoped>
.cms-page{color:var(--text-primary)}.cms-shell{min-height:100%;padding:24px 16px calc(112px + env(safe-area-inset-bottom));background:var(--app-background);max-width:1100px;margin:auto}.cms-intro{margin-bottom:20px}.eyebrow{margin:0 0 5px;color:var(--poliland-green);font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:.1em}.cms-intro h1{margin:0;font-size:clamp(24px,6vw,34px)}.cms-intro p:last-child{color:var(--text-secondary);font-size:13px}.tabs{display:flex;gap:8px;overflow:auto;margin-bottom:16px;padding-bottom:4px}.tabs button,.secondary,.primary,.danger{min-height:44px;border:1px solid var(--border-default);border-radius:var(--radius-control);padding:0 14px;font:inherit;font-size:12px;font-weight:700;cursor:pointer;white-space:nowrap}.tabs button{background:var(--surface-primary);color:var(--text-secondary)}.tabs button.active,.primary{background:var(--poliland-green);color:white;border-color:var(--poliland-green)}.panel{padding:18px;border:1px solid var(--border-default);border-radius:var(--radius-card);background:var(--surface-primary)}.panel-heading,.subheading{display:flex;align-items:center;justify-content:space-between;gap:12px}.panel h2{margin:0;font-size:20px}.panel p{margin:5px 0 18px;color:var(--text-secondary);font-size:13px}.form-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.form-grid label{display:grid;gap:6px;color:var(--text-secondary);font-size:12px;font-weight:700}.form-grid .wide{grid-column:1/-1}input,textarea{width:100%;border:1px solid var(--border-default);border-radius:var(--radius-control);padding:12px;background:var(--surface-primary);color:var(--text-primary);font:inherit;font-size:13px}input:focus,textarea:focus{outline:3px solid color-mix(in srgb,var(--poliland-green) 25%,transparent);border-color:var(--poliland-green)}.hero-preview{width:100%;max-height:220px;object-fit:cover;border-radius:var(--radius-control);margin-top:6px}.subheading{margin:28px 0 12px}.subheading h3{margin:0;font-size:16px}.secondary{background:var(--surface-muted);color:var(--text-primary)}.feature-row{display:grid;grid-template-columns:80px 1fr 2fr 70px auto;gap:8px;margin-bottom:8px}.danger{background:transparent;color:var(--status-danger);border-color:color-mix(in srgb,var(--status-danger) 35%,var(--border-default))}.notice{padding:12px 14px;border-radius:var(--radius-control);font-size:13px}.notice.success{background:var(--status-success-bg);color:var(--poliland-green)}.notice.error{background:#fff0ef;color:var(--status-danger)}.state{padding:48px 16px;text-align:center;color:var(--text-secondary)}@media(max-width:680px){.panel-heading,.subheading{align-items:stretch;flex-direction:column}.form-grid{grid-template-columns:1fr}.form-grid .wide{grid-column:auto}.feature-row{grid-template-columns:1fr 1fr}.feature-row input:nth-child(3){grid-column:1/-1}.feature-row .danger{grid-column:2}.panel{padding:14px}}
</style>
